<script lang="ts">
 import { onMount } from 'svelte'; import { request, uploadFile } from './api'; import { PageHeader, RefreshButton } from './ui';
 type Person={id:string;full_name:string}; type Message={id:string;body:string;created_at:string;author_name:string;file_id:string|null}; type Thread={id:string;title:string;kind:string;members:Person[];messages:Message[]}; type Meeting={id:string;title:string;join_url:string;starts_at:string;ends_at:string};
 let threads=$state<Thread[]>([]),people=$state<Person[]>([]),meetings=$state<Meeting[]>([]),selected=$state(''),title=$state(''),kind=$state('group'),members=$state<string[]>([]),body=$state(''),attachment=$state<File|null>(null),meetingTitle=$state(''),meetingUrl=$state(''),meetingStart=$state(''),meetingEnd=$state(''),error=$state(''),loading=$state(true),saving=$state(false);
 let active=$derived(threads.find(x=>x.id===selected)??threads[0]);
 async function loadMeetings(threadId:string){meetings=threadId?await request<Meeting[]>(`/v1/collaboration/${threadId}/meetings`):[];}
 async function load(){loading=true;try{const [rooms,users]=await Promise.all([request<Thread[]>('/v1/admin/collaboration'),request<Person[]>('/v1/colleagues')]);threads=rooms;people=users;selected||=(rooms[0]?.id??'');await loadMeetings(selected);}catch(cause){error=cause instanceof Error?cause.message:'Kolaborasi tidak dapat dimuat.';}finally{loading=false;}}
 async function create(){saving=true;error='';try{await request('/v1/admin/collaboration',{method:'POST',body:JSON.stringify({title,kind,member_ids:members})});title='';members=[];await load();}catch(cause){error=cause instanceof Error?cause.message:'Ruang tidak dapat dibuat.';}finally{saving=false;}}
 async function send(){if(!active)return;saving=true;error='';try{let file_id:string|null=null;const file=attachment;if(file){const data_base64=await new Promise<string>((ok,bad)=>{const reader=new FileReader();reader.onload=()=>ok(String(reader.result));reader.onerror=bad;reader.readAsDataURL(file);});file_id=(await uploadFile({file_name:file.name,content_type:file.type||'application/octet-stream',data_base64})).id;}await request(`/v1/admin/collaboration/${active.id}/messages`,{method:'POST',body:JSON.stringify({body,file_id})});body='';attachment=null;await load();}catch(cause){error=cause instanceof Error?cause.message:'Pesan tidak dapat dikirim.';}finally{saving=false;}}
 async function choose(id:string){selected=id;try{await loadMeetings(id);}catch(cause){error=cause instanceof Error?cause.message:'Jadwal rapat tidak dapat dimuat.';}}
 async function scheduleMeeting(){if(!active)return;saving=true;error='';try{if(!meetingTitle.trim()||!meetingUrl.trim()||!meetingStart||!meetingEnd)throw new Error('Lengkapi judul, tautan, mulai, dan selesai rapat.');await request(`/v1/collaboration/${active.id}/meetings`,{method:'POST',body:JSON.stringify({title:meetingTitle,join_url:meetingUrl,starts_at:new Date(meetingStart).toISOString(),ends_at:new Date(meetingEnd).toISOString()})});meetingTitle='';meetingUrl='';meetingStart='';meetingEnd='';await loadMeetings(active.id);}catch(cause){error=cause instanceof Error?cause.message:'Rapat tidak dapat dijadwalkan.';}finally{saving=false;}}
 onMount(()=>{void load();const stream=new EventSource('/v1/events/stream');stream.addEventListener('pulse',()=>void load());stream.onerror=()=>{};return()=>stream.close();});
</script>
<main class="workspace-page"><PageHeader title="Collaboration" description="Percakapan kerja, anggota, lampiran, dan jadwal rapat dalam ruang tenant yang sama." backHref="/admin/dashboard"/>{#if error}<p class="alert">{error}</p>{/if}<section class="layout"><aside class="panel"><form novalidate onsubmit={(e)=>{e.preventDefault();void create();}}><h2>Ruang baru</h2><input bind:value={title} placeholder="Nama ruang" required/><select bind:value={kind}><option value="group">Tim</option><option value="project">Proyek</option><option value="personal">Pribadi</option></select><label>Anggota<select multiple bind:value={members}>{#each people as person}<option value={person.id}>{person.full_name}</option>{/each}</select></label><button disabled={saving}>Buat ruang</button></form><nav>{#each threads as thread (thread.id)}<button class:chosen={active?.id===thread.id} onclick={()=>void choose(thread.id)}><strong>{thread.title}</strong><small>{thread.members.length} anggota</small></button>{/each}</nav></aside><section class="panel conversation">{#if active}<header><div><h2>{active.title}</h2><p>{active.members.map(x=>x.full_name).join(', ')}</p></div><RefreshButton onclick={load} label="Muat ulang"/></header><section class="meetings"><h3>Rapat</h3>{#each meetings as meeting(meeting.id)}<a href={meeting.join_url} target="_blank" rel="noreferrer"><strong>{meeting.title}</strong><small>{new Date(meeting.starts_at).toLocaleString('id-ID')} — {new Date(meeting.ends_at).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}</small></a>{:else}<small>Belum ada rapat terjadwal.</small>{/each}<form class="meeting-form" novalidate onsubmit={(e)=>{e.preventDefault();void scheduleMeeting();}}><input bind:value={meetingTitle} placeholder="Judul rapat" required/><input bind:value={meetingUrl} type="url" placeholder="https://meet…" required/><input bind:value={meetingStart} type="datetime-local" required/><input bind:value={meetingEnd} type="datetime-local" required/><button class="quiet" disabled={saving}>Jadwalkan</button></form></section><div class="messages">{#each active.messages as message (message.id)}<article><strong>{message.author_name}</strong><p>{message.body}</p>{#if message.file_id}<small>Lampiran tersimpan di Berkas</small>{/if}<small>{new Date(message.created_at).toLocaleString('id-ID')}</small></article>{:else}<p class="muted">Belum ada pesan.</p>{/each}</div><form novalidate onsubmit={(e)=>{e.preventDefault();void send();}}><textarea bind:value={body} placeholder="Tulis pesan" required></textarea><input type="file" onchange={(e)=>attachment=e.currentTarget.files?.[0]??null}/><button disabled={saving}>Kirim</button></form>{/if}</section></section></main>
<style>.workspace-page,.layout{display:grid;gap:12px}.layout{grid-template-columns:300px 1fr}.panel{padding:16px;border-radius:var(--radius)}form,nav,.messages,.meetings{display:grid;gap:8px}nav{margin-top:14px}nav button{text-align:left}h2{font-size:15px}h3{margin:0;font-size:13px}small,p{display:block;color:var(--muted);font-size:12px}.chosen{border-color:var(--accent)}.messages{min-height:260px;align-content:start}.messages article,.meetings{padding:10px;border:1px solid var(--line);border-radius:var(--radius-sm)}.meetings a{display:grid;gap:2px;color:inherit;text-decoration:none}.meeting-form{grid-template-columns:repeat(2,minmax(0,1fr));padding-top:8px;border-top:1px solid var(--line)}textarea{min-height:70px}.alert{color:var(--danger)}@media(max-width:720px){.layout,.meeting-form{grid-template-columns:1fr}}</style>
